import{_ as n,c as a,o as e,ag as i}from"./chunks/framework.B-XtCDNB.js";const g=JSON.parse('{"title":"Windows cross-build sample","description":"Windows cross-build sample Cross-compiling a Vala (or C/GTK) project for Windows from Linux, based on the archived GNOME Wiki page Projects/Vala/Win32CrossBuildSample. The wiki walked through CMake,...","frontmatter":{},"headers":[],"relativePath":"sample-code/other/win32-cross-build.md","filePath":"sample-code/other/win32-cross-build.md","lastUpdated":1785985742000}'),o={name:"sample-code/other/win32-cross-build.md"};function t(p,s,l,r,d,c){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="windows-cross-build-sample" tabindex="-1">Windows cross-build sample <a class="header-anchor" href="#windows-cross-build-sample" aria-label="Permalink to &quot;Windows cross-build sample&quot;">​</a></h1><p>Cross-compiling a Vala (or C/GTK) project for Windows from Linux, based on the archived GNOME Wiki page <a href="https://wiki.gnome.org/Projects/Vala/Win32CrossBuildSample" target="_blank" rel="noreferrer">Projects/Vala/Win32CrossBuildSample</a>.</p><p>The wiki walked through <strong>CMake</strong>, an old MinGW toolchain (<code>i586-mingw32msvc</code>), GTK+ 2 bundles, and <strong>NSIS</strong> packaging. Those pieces are mostly historical: current developers typically use <strong>Meson</strong> with a <strong>MinGW-w64</strong> toolchain and GTK 3 or GTK 4 Windows runtimes from <a href="https://github.com/wingtk/gvsbuild" target="_blank" rel="noreferrer">gvsbuild</a> or similar distributors.</p><h2 id="what-the-wiki-described-cmake-gtk-2-bundle" tabindex="-1">What the wiki described (CMake + GTK+ 2 bundle) <a class="header-anchor" href="#what-the-wiki-described-cmake-gtk-2-bundle" aria-label="Permalink to &quot;What the wiki described (CMake + GTK+ 2 bundle)&quot;">​</a></h2><p>The archive suggested:</p><ul><li>Installing <code>mingw32</code>, CMake, NSIS, and a pre-built GTK+ bundle for Windows.</li><li>Unzipping the bundle under <code>win32/</code> and rewriting every <code>.pc</code> file’s <code>prefix=</code> so <code>PKG_CONFIG_PATH</code> points at the bundle.</li><li>A <code>Toolchain.cmake</code> that sets <code>CMAKE_SYSTEM_NAME</code> to <code>Windows</code> and selects <code>i586-mingw32msvc-gcc</code>.</li><li>A tiny <code>hello-world.c</code> linked with <code>gtk+-2.0</code> to prove the cross prefix works, then running the <code>.exe</code> with Wine.</li></ul><p>That flow is useful as background reading, but the exact package names, URLs, and compiler triples on modern distributions differ. Treat the wiki as a narrative, not copy-paste instructions.</p><h2 id="meson-cross-compilation-for-windows" tabindex="-1">Meson cross-compilation for Windows <a class="header-anchor" href="#meson-cross-compilation-for-windows" aria-label="Permalink to &quot;Meson cross-compilation for Windows&quot;">​</a></h2><p>Meson is the build system most Vala and GTK projects use today. A typical approach:</p><ol><li>Install a MinGW-w64 cross compiler (for example <code>x86_64-w64-mingw32-gcc</code> on Debian/Ubuntu via <code>gcc-mingw-w64-x86-64</code>).</li><li>Install or build Windows copies of GLib/GTK and produce a <strong>pkg-config</strong> tree (gvsbuild output is common).</li><li>Write a Meson <strong>cross file</strong> describing the host system and tool paths.</li></ol><p><code>mingw-w64.ini</code> (adjust paths to your SDK root):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[binaries]</span></span>
<span class="line"><span>c = &#39;x86_64-w64-mingw32-gcc&#39;</span></span>
<span class="line"><span>cpp = &#39;x86_64-w64-mingw32-g++&#39;</span></span>
<span class="line"><span>ar = &#39;x86_64-w64-mingw32-ar&#39;</span></span>
<span class="line"><span>strip = &#39;x86_64-w64-mingw32-strip&#39;</span></span>
<span class="line"><span>pkg-config = &#39;pkg-config&#39;</span></span>
<span class="line"><span>windres = &#39;x86_64-w64-mingw32-windres&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[built-in options]</span></span>
<span class="line"><span>c_args = [&#39;-I/path/to/windows-deps/include&#39;]</span></span>
<span class="line"><span>c_link_args = [&#39;-L/path/to/windows-deps/lib&#39;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[host_machine]</span></span>
<span class="line"><span>system = &#39;windows&#39;</span></span>
<span class="line"><span>cpu_family = &#39;x86_64&#39;</span></span>
<span class="line"><span>cpu = &#39;x86_64&#39;</span></span>
<span class="line"><span>endian = &#39;little&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[properties]</span></span>
<span class="line"><span>pkg_config_libdir = &#39;/path/to/windows-deps/lib/pkgconfig&#39;</span></span></code></pre></div><p><code>meson.build</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project(&#39;hello&#39;, &#39;c&#39;, vala: true)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>glib_dep = dependency(&#39;glib-2.0&#39;)</span></span>
<span class="line"><span>exe = executable(&#39;hello&#39;, &#39;main.vala&#39;, dependencies: glib_dep)</span></span></code></pre></div><p>Configure and compile from your project root:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PKG_CONFIG_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/windows-deps/lib/pkgconfig</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meson</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-windows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cross-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mingw-w64.ini</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meson</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-windows</span></span></code></pre></div><p>Meson then passes the correct <code>--pkg</code> arguments to <code>valac</code> and links against the Windows libraries described by the cross environment. Copy required DLLs next to the <code>.exe</code> (or run an install step that stages a runtime tree) before testing on Windows.</p><p>For GTK applications, follow upstream guidance for <a href="https://www.gtk.org/docs/installations/windows/" target="_blank" rel="noreferrer">GTK on Windows</a> and keep your SDK versions aligned with what your dependencies expect.</p>`,18)])])}const u=n(o,[["render",t]]);export{g as __pageData,u as default};
